example.text:
{
  _default = {
    down_hold_release = {
      description = "Default: no default actions";
      enable = true;
    };
    down_press_release = {
      description = "Default: dim down room lights";
      enable = true;
    };
    off_hold_release = {
      description = "Default: turn off all lights";
      enable = true;
    };
    off_press_release = {
      description = "Default: turn off room lights";
      enable = true;
    };
    on_hold_release = {
      description = "Default: turn on all lights at maximum brightness";
      enable = true;
    };
    on_press_release = {
      description = "Default: turn on room lights";
      enable = true;
    };
    up_hold_release = {
      description = "Default: no default actions";
      enable = true;
    };
    up_press_release = {
      description = "Default: dim up room lights";
      enable = true;
    };
  };
  kitchen = {
    off_press_release = {
      description = "Turn off kitchen lights only";
      enable = true;
    };
    on_press_release = {
      description = "Turn on kitchen lights and fan";
      enable = true;
      extra_actions = [
        {
          message = "{\"state\":\"ON\"}";
          topic = "zigbee2mqtt/Fläkt/set";
          type = "mqtt";
        }
      ];
    };
  };
}

{
  all_lights_on = [
    "echo 'All lights turned on'"
    {
      scene = "max";
      type = "scene";
    }
  ];
  security_armed = [
    "echo 'Security system armed'"
    {
      message = "{\"armed\":true}";
      topic = "zigbee2mqtt/security/state";
      type = "mqtt";
    }
  ];
}

{
  button_single_press = {
    actions = [
      {
        message = "{\"state\":\"TOGGLE\"}";
        topic = "zigbee2mqtt/living_room_lights/set";
        type = "mqtt";
      }
    ];
    description = "Toggle living room lights on button single press";
    enable = true;
    message = "single";
    topic = "zigbee2mqtt/living_room_button/action";
  };
  motion_alert = {
    actions = [
      "echo 'Motion detected outside!' | wall"
      {
        command = "/nix/store/9yrxszw0fbyx68dbr4nbcnb408vqxgya-libnotify-0.8.8/bin/notify-send 'Security' 'Motion detected outside'";
        type = "shell";
      }
    ];
    description = "Send notification on motion detected";
    enable = true;
    message = "true";
    topic = "zigbee2mqtt/outdoor_motion/occupancy";
  };
}

{
  kitchen = {
    lights_turned_on = [
      "echo 'Kitchen lights activated'"
    ];
    motion_detected = [
      "echo 'Motion in kitchen'"
      {
        message = "{\"state\":\"ON\"}";
        topic = "zigbee2mqtt/Fläkt/set";
        type = "mqtt";
      }
    ];
  };
}

{
  bedtime = {
    actions = [
      {
        scene = "night";
        type = "scene";
      }
    ];
    description = "Prepare for bed";
    enable = true;
    schedule = "0 22 * * *";
  };
  morning_wakeup = {
    actions = [
      {
        scene = "morning";
        type = "scene";
      }
      "echo 'Good morning!'"
    ];
    conditions = [
      {
        type = "someone_home";
        value = true;
      }
    ];
    description = "Gentle morning lights";
    enable = true;
    schedule = {
      days = [
        "mon"
        "tue"
        "wed"
        "thu"
        "fri"
      ];
      end = "07:00";
      start = "06:30";
    };
  };
}

